// ── Custom tooltip ─────────────────────────────────────────────────────────
const CustomTooltip = ({ active, payload, label }) => {
  if (!active || !payload?.length) return null
  return (
    <div style={{
      background: '#0d1a27', border: '1px solid var(--border-bright)',
      borderRadius: '6px', padding: '10px 14px', fontSize: '11px',
      fontFamily: 'var(--font-mono)',
    }}>
      {label && <div style={{ color: 'var(--text-secondary)', marginBottom: '6px' }}>{label}</div>}
      {payload.map((p, i) => (
        <div key={i} style={{ color: p.color, marginBottom: '2px' }}>
          {p.name}: <strong>{typeof p.value === 'number' ? p.value.toFixed(1) : p.value}</strong>
        </div>
      ))}
    </div>
  )
}

// ── Colours ────────────────────────────────────────────────────────────────
const C = {
  blue:   '#00c8ff',
  teal:   '#00e5b0',
  amber:  '#f5a623',
  red:    '#e05a5a',
  purple: '#8b7cf8',
  blueDim:'#0a3a50',
  grid:   '#121f2e',
  label:  '#3a5a78',
}

const RADIAN = Math.PI / 180
const PieLabel = ({ cx, cy, midAngle, innerRadius, outerRadius, percent, name }) => {
  if (percent < 0.07) return null
  const r = innerRadius + (outerRadius - innerRadius) * 0.5
  const x = cx + r * Math.cos(-midAngle * RADIAN)
  const y = cy + r * Math.sin(-midAngle * RADIAN)
  return (
    <text x={x} y={y} fill="white" textAnchor="middle" dominantBaseline="central"
      style={{ fontSize: '10px', fontFamily: 'var(--font-mono)', fontWeight: 600 }}>
      {(percent * 100).toFixed(0)}%
    </text>
  )
}

